const MOFID_ORBITAL_CSS="/*\r\n\r\n    Tooplate 2167 Orbital\r\n\r\n    https://www.tooplate.com/view/2167-orbital\r\n\r\n    Free HTML CSS Template\r\n\r\n*/\r\n\r\n/* ORBITAL // 297 - Void and Neon presentation template */\r\n\r\n:root {\r\n  --void: #050505;\r\n  --violet: #8b5cf6;\r\n  --cyan: #06b6d4;\r\n  --white: #ffffff;\r\n  --dim: rgba(255, 255, 255, 0.55);\r\n  --faint: rgba(255, 255, 255, 0.32);\r\n  --ease: cubic-bezier(0.16, 1, 0.3, 1);\r\n  --ring-radius: 360px;\r\n}\r\n\r\n* { margin: 0; padding: 0; box-sizing: border-box; }\r\n\r\nhtml { scroll-behavior: smooth; }\r\n\r\nbody {\r\n  background: var(--void);\r\n  color: var(--white);\r\n  font-family: 'Space Grotesk', sans-serif;\r\n  overflow-x: hidden;\r\n  -webkit-font-smoothing: antialiased;\r\n}\r\n\r\na { color: inherit; text-decoration: none; }\r\n\r\n/* Ambient void layers */\r\n.aura {\r\n  position: fixed;\r\n  inset: -25%;\r\n  background: radial-gradient(circle at 50% 44%, rgba(58, 28, 92, 0.6), rgba(24, 12, 46, 0.22) 34%, transparent 64%);\r\n  z-index: 0;\r\n  pointer-events: none;\r\n  animation: drift 20s ease-in-out infinite alternate;\r\n}\r\n\r\n.stars {\r\n  position: fixed;\r\n  inset: 0;\r\n  z-index: 0;\r\n  pointer-events: none;\r\n  opacity: 0.5;\r\n  background-image:\r\n    radial-gradient(1px 1px at 12% 22%, rgba(255, 255, 255, 0.7), transparent),\r\n    radial-gradient(1px 1px at 78% 14%, rgba(255, 255, 255, 0.5), transparent),\r\n    radial-gradient(1px 1px at 34% 68%, rgba(139, 92, 246, 0.6), transparent),\r\n    radial-gradient(1px 1px at 64% 82%, rgba(6, 182, 212, 0.5), transparent),\r\n    radial-gradient(1px 1px at 88% 54%, rgba(255, 255, 255, 0.4), transparent),\r\n    radial-gradient(1px 1px at 22% 88%, rgba(255, 255, 255, 0.45), transparent),\r\n    radial-gradient(1px 1px at 50% 32%, rgba(255, 255, 255, 0.3), transparent);\r\n}\r\n\r\n@keyframes drift {\r\n  from { transform: translate3d(-2%, -1%, 0) scale(1); }\r\n  to { transform: translate3d(2%, 3%, 0) scale(1.14); }\r\n}\r\n\r\n/* Navigation */\r\n.nav {\r\n  position: fixed;\r\n  top: 0; left: 0; right: 0;\r\n  z-index: 50;\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: space-between;\r\n  padding: 26px clamp(20px, 5vw, 64px);\r\n  backdrop-filter: blur(6px);\r\n}\r\n\r\n.logo {\r\n  font-family: 'JetBrains Mono', monospace;\r\n  font-size: 14px;\r\n  font-weight: 500;\r\n  letter-spacing: 3px;\r\n  color: var(--white);\r\n}\r\n.logo span { color: var(--cyan); }\r\n\r\n.nav-links {\r\n  display: flex;\r\n  gap: 38px;\r\n  list-style: none;\r\n  align-items: center;\r\n}\r\n.nav-links a {\r\n  font-family: 'JetBrains Mono', monospace;\r\n  font-size: 12px;\r\n  letter-spacing: 2px;\r\n  color: var(--faint);\r\n  transition: color 0.5s var(--ease), text-shadow 0.5s var(--ease);\r\n  position: relative;\r\n}\r\n.nav-links a::before {\r\n  content: '';\r\n  width: 4px; height: 4px;\r\n  border-radius: 50%;\r\n  background: var(--cyan);\r\n  position: absolute;\r\n  left: -12px; top: 50%;\r\n  transform: translateY(-50%) scale(0);\r\n  transition: transform 0.5s var(--ease);\r\n  box-shadow: 0 0 8px var(--cyan);\r\n}\r\n.nav-links a:hover {\r\n  color: var(--white);\r\n  text-shadow: 0 0 14px rgba(6, 182, 212, 0.7);\r\n}\r\n.nav-links a:hover::before { transform: translateY(-50%) scale(1); }\r\n\r\n.menu-toggle {\r\n  display: none;\r\n  flex-direction: column;\r\n  gap: 5px;\r\n  background: none;\r\n  border: none;\r\n  cursor: pointer;\r\n  padding: 6px;\r\n}\r\n.menu-toggle span {\r\n  width: 24px; height: 2px;\r\n  background: var(--white);\r\n  transition: transform 0.4s var(--ease), opacity 0.4s var(--ease);\r\n}\r\n\r\n/* Mobile menu overlay */\r\n.mobile-menu {\r\n  position: fixed;\r\n  inset: 0;\r\n  z-index: 49;\r\n  background: rgba(5, 5, 5, 0.96);\r\n  backdrop-filter: blur(16px);\r\n  display: flex;\r\n  flex-direction: column;\r\n  align-items: center;\r\n  justify-content: center;\r\n  gap: 30px;\r\n  padding: 80px 24px;\r\n  overflow-y: auto;\r\n  opacity: 0;\r\n  visibility: hidden;\r\n  transition: opacity 0.5s var(--ease), visibility 0.5s var(--ease);\r\n}\r\n.mobile-menu.open { opacity: 1; visibility: visible; }\r\n.mobile-menu a {\r\n  font-family: 'JetBrains Mono', monospace;\r\n  font-size: 20px;\r\n  letter-spacing: 3px;\r\n  color: var(--dim);\r\n  transition: color 0.4s var(--ease);\r\n}\r\n.mobile-menu a:hover { color: var(--cyan); }\r\n\r\n/* Hero with orbital ring */\r\n.hero {\r\n  position: relative;\r\n  z-index: 2;\r\n  height: 100vh;\r\n  min-height: 640px;\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n}\r\n\r\n.stage {\r\n  position: absolute;\r\n  inset: 0;\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  perspective: 1300px;\r\n  cursor: grab;\r\n  touch-action: pan-y;\r\n  user-select: none;\r\n  -webkit-user-select: none;\r\n}\r\n.stage.dragging { cursor: grabbing; }\r\n.stage.dragging .panel { cursor: grabbing; }\r\n\r\n.parallax {\r\n  position: relative;\r\n  width: 1px; height: 1px;\r\n  transform-style: preserve-3d;\r\n  transition: transform 0.6s var(--ease);\r\n}\r\n\r\n.hero-text {\r\n  position: absolute;\r\n  top: 50%; left: 50%;\r\n  transform: translate(-50%, -50%) translateZ(40px);\r\n  text-align: center;\r\n  width: 90vw;\r\n  max-width: 760px;\r\n  pointer-events: none;\r\n}\r\n.eyebrow {\r\n  font-family: 'JetBrains Mono', monospace;\r\n  font-size: clamp(10px, 1.4vw, 13px);\r\n  letter-spacing: 6px;\r\n  color: var(--cyan);\r\n  text-shadow: 0 0 16px rgba(6, 182, 212, 0.6);\r\n  margin-bottom: 22px;\r\n}\r\n.hero-text h1 {\r\n  font-size: clamp(2.8rem, 9vw, 6.4rem);\r\n  font-weight: 700;\r\n  line-height: 0.94;\r\n  letter-spacing: -0.03em;\r\n  color: var(--white);\r\n  text-shadow: 0 0 38px rgba(255, 255, 255, 0.28), 0 0 80px rgba(139, 92, 246, 0.32);\r\n}\r\n.hero-text p {\r\n  margin-top: 26px;\r\n  font-size: clamp(0.92rem, 2vw, 1.08rem);\r\n  color: var(--dim);\r\n  letter-spacing: 0.4px;\r\n  max-width: 440px;\r\n  margin-left: auto;\r\n  margin-right: auto;\r\n}\r\n\r\n/* The orbital ring */\r\n.ring-tilt {\r\n  position: absolute;\r\n  top: 0; left: 0;\r\n  transform-style: preserve-3d;\r\n  transform: rotateX(var(--tiltX, -20deg)) scale3d(var(--zoom, 1), var(--zoom, 1), var(--zoom, 1));\r\n  transition: transform 0.8s var(--ease);\r\n}\r\n.ring {\r\n  position: absolute;\r\n  top: 0; left: 0;\r\n  transform-style: preserve-3d;\r\n  will-change: transform;\r\n}\r\n\r\n.panel {\r\n  position: absolute;\r\n  top: 0; left: 0;\r\n  width: 158px;\r\n  height: 210px;\r\n  margin-left: -79px;\r\n  margin-top: -105px;\r\n  border-radius: 18px;\r\n  background: rgba(255, 255, 255, 0.035);\r\n  backdrop-filter: blur(9px);\r\n  -webkit-backdrop-filter: blur(8px);\r\n  box-shadow: inset 0 0 34px rgba(139, 92, 246, 0.16), 0 0 42px rgba(6, 182, 212, 0.1);\r\n  transform: rotateY(var(--ry)) translateZ(var(--tz)) rotateZ(var(--rz)) scale(var(--s, 1));\r\n  transition: transform 0.7s var(--ease), box-shadow 0.7s var(--ease);\r\n  cursor: pointer;\r\n}\r\n/* 1px gradient border via masked pseudo element */\r\n.panel::after {\r\n  content: '';\r\n  position: absolute;\r\n  inset: 0;\r\n  border-radius: inherit;\r\n  padding: 1px;\r\n  background: linear-gradient(to bottom right, rgba(139, 92, 246, 0.5), rgba(6, 182, 212, 0.2));\r\n  -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);\r\n  -webkit-mask-composite: xor;\r\n  mask-composite: exclude;\r\n  transition: background 0.7s var(--ease), opacity 0.7s var(--ease);\r\n}\r\n.panel:hover {\r\n  --s: 1.1;\r\n  box-shadow: inset 0 0 44px rgba(139, 92, 246, 0.3), 0 0 60px rgba(6, 182, 212, 0.4);\r\n}\r\n.panel:hover::after {\r\n  background: linear-gradient(to bottom right, rgba(139, 92, 246, 0.95), rgba(6, 182, 212, 0.7));\r\n}\r\n.panel .p-num {\r\n  font-family: 'JetBrains Mono', monospace;\r\n  font-size: 10px;\r\n  letter-spacing: 2px;\r\n  color: var(--cyan);\r\n}\r\n.panel .p-label {\r\n  font-size: 14px;\r\n  font-weight: 600;\r\n  letter-spacing: 0.5px;\r\n}\r\n.panel .p-meta {\r\n  font-family: 'JetBrains Mono', monospace;\r\n  font-size: 9px;\r\n  letter-spacing: 1px;\r\n  color: var(--faint);\r\n}\r\n\r\n/* Two stacked faces per panel, crossfaded by the toggle with a staggered delay */\r\n.panel-face {\r\n  position: absolute;\r\n  inset: 0;\r\n  border-radius: inherit;\r\n  transition: opacity 0.8s var(--ease);\r\n  transition-delay: calc(var(--i, 0) * 0.045s);\r\n}\r\n.panel-face--text {\r\n  padding: 18px;\r\n  display: flex;\r\n  flex-direction: column;\r\n  justify-content: space-between;\r\n  opacity: 1;\r\n}\r\n.panel-face--image {\r\n  overflow: hidden;\r\n  opacity: 0;\r\n  background: linear-gradient(140deg, #1a1030, #0a1f26);\r\n}\r\n.panel-face--image img {\r\n  width: 100%;\r\n  height: 100%;\r\n  object-fit: cover;\r\n  display: block;\r\n  transform: scale(1.08);\r\n  transition: transform 1.3s var(--ease);\r\n  transition-delay: calc(var(--i, 0) * 0.045s);\r\n}\r\n.panel-scrim {\r\n  position: absolute;\r\n  inset: 0;\r\n  background:\r\n    linear-gradient(to top, rgba(5, 5, 5, 0.92), rgba(5, 5, 5, 0.08) 56%),\r\n    linear-gradient(140deg, rgba(139, 92, 246, 0.4), rgba(6, 182, 212, 0.28));\r\n  transition: opacity 0.6s var(--ease);\r\n}\r\n.panel:hover .panel-scrim { opacity: 0; }\r\n.panel-cap {\r\n  position: absolute;\r\n  bottom: 14px;\r\n  left: 16px;\r\n  right: 16px;\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 9px;\r\n  font-size: 14px;\r\n  font-weight: 600;\r\n  letter-spacing: 0.5px;\r\n  color: var(--white);\r\n  text-shadow: 0 2px 12px rgba(0, 0, 0, 0.95), 0 0 22px rgba(0, 0, 0, 0.7);\r\n}\r\n\r\n/* Toggle ON state */\r\n.visuals-on .panel-face--text { opacity: 0; }\r\n.visuals-on .panel-face--image { opacity: 1; }\r\n.visuals-on .panel-face--image img { transform: scale(1); }\r\n\r\n/* HUD controls docked bottom right */\r\n.hero-controls {\r\n  position: absolute;\r\n  right: clamp(18px, 4vw, 44px);\r\n  bottom: clamp(80px, 12vh, 110px);\r\n  z-index: 5;\r\n  display: flex;\r\n  flex-direction: column;\r\n  align-items: flex-end;\r\n  gap: 16px;\r\n}\r\n.ctrl {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 10px;\r\n}\r\n.ctrl-label {\r\n  font-family: 'JetBrains Mono', monospace;\r\n  font-size: 10px;\r\n  letter-spacing: 2px;\r\n  color: var(--faint);\r\n}\r\n.switch {\r\n  position: relative;\r\n  width: 44px;\r\n  height: 24px;\r\n  border-radius: 24px;\r\n  background: rgba(255, 255, 255, 0.06);\r\n  border: 1px solid rgba(255, 255, 255, 0.14);\r\n  cursor: pointer;\r\n  padding: 0;\r\n  transition: background 0.6s var(--ease), border-color 0.6s var(--ease), box-shadow 0.6s var(--ease);\r\n}\r\n.switch .knob {\r\n  position: absolute;\r\n  top: 2px;\r\n  left: 2px;\r\n  width: 18px;\r\n  height: 18px;\r\n  border-radius: 50%;\r\n  background: var(--dim);\r\n  transition: transform 0.6s var(--ease), background 0.6s var(--ease), box-shadow 0.6s var(--ease);\r\n}\r\n.switch[aria-checked=\"true\"] {\r\n  background: linear-gradient(to right, var(--violet), var(--cyan));\r\n  border-color: rgba(6, 182, 212, 0.8);\r\n  box-shadow: 0 0 20px rgba(6, 182, 212, 0.5);\r\n}\r\n.switch[aria-checked=\"true\"] .knob {\r\n  transform: translateX(20px);\r\n  background: var(--white);\r\n  box-shadow: 0 0 12px rgba(255, 255, 255, 0.9);\r\n}\r\n.switch:focus-visible {\r\n  outline: 2px solid var(--cyan);\r\n  outline-offset: 4px;\r\n}\r\n\r\n/* 3 step ring spacing */\r\n.spacing {\r\n  display: flex;\r\n  gap: 3px;\r\n  padding: 3px;\r\n  border-radius: 24px;\r\n  background: rgba(255, 255, 255, 0.05);\r\n  border: 1px solid rgba(255, 255, 255, 0.12);\r\n}\r\n.spacing-step {\r\n  width: 26px;\r\n  height: 22px;\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  background: none;\r\n  border: none;\r\n  border-radius: 18px;\r\n  cursor: pointer;\r\n  transition: background 0.5s var(--ease);\r\n}\r\n.spacing-step i {\r\n  display: block;\r\n  border-radius: 50%;\r\n  background: var(--faint);\r\n  transition: background 0.5s var(--ease), box-shadow 0.5s var(--ease);\r\n}\r\n.spacing-step:nth-child(1) i { width: 5px; height: 5px; }\r\n.spacing-step:nth-child(2) i { width: 8px; height: 8px; }\r\n.spacing-step:nth-child(3) i { width: 11px; height: 11px; }\r\n.spacing-step.is-active { background: rgba(6, 182, 212, 0.14); }\r\n.spacing-step.is-active i { background: var(--cyan); box-shadow: 0 0 10px var(--cyan); }\r\n.spacing-step:focus-visible { outline: 2px solid var(--cyan); outline-offset: 2px; }\r\n\r\n.scroll-cue {\r\n  position: absolute;\r\n  bottom: 34px; left: 50%;\r\n  transform: translateX(-50%);\r\n  z-index: 3;\r\n  font-family: 'JetBrains Mono', monospace;\r\n  font-size: 10px;\r\n  letter-spacing: 3px;\r\n  color: var(--faint);\r\n  display: flex;\r\n  flex-direction: column;\r\n  align-items: center;\r\n  gap: 10px;\r\n}\r\n.scroll-cue .line {\r\n  width: 1px; height: 38px;\r\n  background: linear-gradient(var(--cyan), transparent);\r\n  animation: pulse-line 2.4s ease-in-out infinite;\r\n}\r\n@keyframes pulse-line {\r\n  0%, 100% { opacity: 0.3; }\r\n  50% { opacity: 1; }\r\n}\r\n\r\n/* Content sections */\r\n.section {\r\n  position: relative;\r\n  z-index: 2;\r\n  padding: clamp(90px, 14vh, 160px) clamp(20px, 6vw, 90px);\r\n  max-width: 1240px;\r\n  margin: 0 auto;\r\n}\r\n.section-head {\r\n  margin-bottom: 64px;\r\n  max-width: 620px;\r\n}\r\n.section-head .eyebrow { text-align: left; margin-bottom: 18px; }\r\n.section-head h2 {\r\n  font-size: clamp(2rem, 5vw, 3.4rem);\r\n  font-weight: 600;\r\n  line-height: 1.02;\r\n  letter-spacing: -0.02em;\r\n  text-shadow: 0 0 30px rgba(255, 255, 255, 0.16);\r\n}\r\n.section-head p {\r\n  margin-top: 20px;\r\n  color: var(--dim);\r\n  font-size: 1.02rem;\r\n  line-height: 1.6;\r\n}\r\n\r\n.features {\r\n  display: grid;\r\n  grid-template-columns: repeat(3, 1fr);\r\n  gap: 22px;\r\n}\r\n.feature {\r\n  position: relative;\r\n  padding: 40px 30px 36px;\r\n  border-radius: 16px;\r\n  background: rgba(255, 255, 255, 0.025);\r\n  border: 1px solid rgba(255, 255, 255, 0.06);\r\n  backdrop-filter: blur(8px);\r\n  overflow: hidden;\r\n  transition: transform 0.7s var(--ease), background 0.7s var(--ease);\r\n}\r\n.feature::before {\r\n  content: '';\r\n  position: absolute;\r\n  top: 0; left: 0; right: 0;\r\n  height: 2px;\r\n  background: var(--cyan);\r\n  box-shadow: 0 0 18px var(--cyan), 0 0 6px var(--cyan);\r\n  animation: pulse-top 3.2s ease-in-out infinite;\r\n}\r\n.feature:nth-child(2)::before { animation-delay: 1s; }\r\n.feature:nth-child(3)::before { animation-delay: 2s; }\r\n@keyframes pulse-top {\r\n  0%, 100% { opacity: 0.35; }\r\n  50% { opacity: 1; }\r\n}\r\n.feature:hover {\r\n  transform: translateY(-6px);\r\n  background: rgba(255, 255, 255, 0.05);\r\n}\r\n.feature .f-index {\r\n  font-family: 'JetBrains Mono', monospace;\r\n  font-size: 12px;\r\n  letter-spacing: 2px;\r\n  color: var(--violet);\r\n  margin-bottom: 22px;\r\n}\r\n.feature h3 {\r\n  font-size: 1.4rem;\r\n  font-weight: 600;\r\n  margin-bottom: 14px;\r\n  letter-spacing: -0.01em;\r\n}\r\n.feature p {\r\n  color: var(--dim);\r\n  font-size: 0.94rem;\r\n  line-height: 1.62;\r\n}\r\n\r\n/* Closing call to action */\r\n.cta {\r\n  position: relative;\r\n  z-index: 2;\r\n  text-align: center;\r\n  padding: clamp(100px, 16vh, 180px) 24px;\r\n}\r\n.cta h2 {\r\n  font-size: clamp(2.2rem, 7vw, 4.6rem);\r\n  font-weight: 700;\r\n  letter-spacing: -0.03em;\r\n  line-height: 1;\r\n  text-shadow: 0 0 40px rgba(139, 92, 246, 0.4);\r\n}\r\n.cta p {\r\n  margin: 24px auto 42px;\r\n  max-width: 460px;\r\n  color: var(--dim);\r\n  font-size: 1.02rem;\r\n}\r\n.btn {\r\n  display: inline-block;\r\n  position: relative;\r\n  font-family: 'JetBrains Mono', monospace;\r\n  font-size: 13px;\r\n  letter-spacing: 3px;\r\n  padding: 18px 42px;\r\n  border-radius: 50px;\r\n  color: var(--white);\r\n  background: rgba(255, 255, 255, 0.04);\r\n  border: 1px solid transparent;\r\n  background-clip: padding-box;\r\n  transition: transform 0.6s var(--ease), box-shadow 0.6s var(--ease);\r\n  overflow: hidden;\r\n}\r\n.btn::after {\r\n  content: '';\r\n  position: absolute;\r\n  inset: 0;\r\n  border-radius: inherit;\r\n  padding: 1px;\r\n  background: linear-gradient(to right, var(--violet), var(--cyan));\r\n  -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);\r\n  -webkit-mask-composite: xor;\r\n  mask-composite: exclude;\r\n}\r\n.btn:hover {\r\n  transform: translateY(-3px) scale(1.04);\r\n  box-shadow: 0 0 40px rgba(139, 92, 246, 0.5), 0 0 18px rgba(6, 182, 212, 0.4);\r\n}\r\n\r\n/* Footer */\r\n.footer {\r\n  position: relative;\r\n  z-index: 2;\r\n  border-top: 1px solid rgba(255, 255, 255, 0.06);\r\n  padding: 44px clamp(20px, 6vw, 64px);\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: space-between;\r\n  flex-wrap: wrap;\r\n  gap: 16px;\r\n}\r\n.footer .logo { font-size: 13px; }\r\n.footer .credit {\r\n  font-family: 'JetBrains Mono', monospace;\r\n  font-size: 11px;\r\n  letter-spacing: 1px;\r\n  color: var(--faint);\r\n}\r\n.footer .credit a { color: var(--dim); transition: color 0.4s var(--ease); }\r\n.footer .credit a:hover { color: var(--cyan); }\r\n\r\n/* Scroll reveal */\r\n.reveal {\r\n  opacity: 0;\r\n  transform: translateY(34px);\r\n  transition: opacity 1s var(--ease), transform 1s var(--ease);\r\n}\r\n.reveal.visible {\r\n  opacity: 1;\r\n  transform: translateY(0);\r\n}\r\n\r\n/* Responsive */\r\n@media (max-width: 900px) {\r\n  .features { grid-template-columns: 1fr; }\r\n}\r\n@media (max-width: 720px) {\r\n  .nav-links { display: none; }\r\n  .menu-toggle { display: flex; }\r\n  :root { --ring-radius: 220px; }\r\n  .panel { width: 124px; height: 168px; margin-left: -62px; margin-top: -84px; }\r\n  .ring-tilt { --tiltX: -14deg; }\r\n}\r\n\r\n/* Reduced motion */\r\n@media (prefers-reduced-motion: reduce) {\r\n  .aura, .ring, .scroll-cue .line, .feature::before { animation: none; }\r\n  .parallax { transition: none; }\r\n  .reveal { opacity: 1; transform: none; transition: none; }\r\n  html { scroll-behavior: auto; }\r\n}\r\n";
const MOFID_LESSON_CSS=":root{--cyan:#00AF9D;--violet:#F32735;--ring-radius:340px}\nbody{font-family:Tahoma,Arial,sans-serif;line-height:1.9;background:#071917;color:#edf8f6;--lesson-border:#ffffff23;--lesson-surface:#0d2424ee}\nbutton,select{font:inherit;cursor:pointer;color:inherit;background:#ffffff0d;border:1px solid var(--lesson-border);border-radius:12px;padding:9px 16px}button:hover{border-color:#00AF9D}button:focus-visible,select:focus-visible,summary:focus-visible{outline:3px solid #00AF9D;outline-offset:4px}button:disabled{opacity:.4;cursor:default}\n.lesson-header{position:relative;z-index:5;display:flex;justify-content:space-between;gap:20px;align-items:center;padding:20px 5vw;border-bottom:1px solid var(--lesson-border)}.actions{display:flex;gap:8px;flex-wrap:wrap}.aura{inset:0;background:radial-gradient(ellipse at 65% 30%,#00af9d26,transparent 65%),radial-gradient(ellipse at 10% 70%,#f3273517,transparent 60%)}\nmain{position:relative;z-index:1}.orbital-intro{padding:55px 5vw 30px;max-width:1400px;margin:auto;display:grid;grid-template-columns:1fr 1fr;align-items:center;gap:24px}.intro-copy{max-width:600px}.intro-copy span{color:#00AF9D}.intro-copy h1{font-size:clamp(28px,4vw,52px);line-height:1.5;margin:12px 0 24px}.intro-copy p{opacity:.8;max-width:60ch}.start{background:#00af9d;color:#062a25;margin-top:24px;font-weight:bold}.orbital-scene{position:relative;min-height:430px;overflow:hidden;isolation:isolate;direction:ltr}.stage{perspective:1100px}.panel{font-family:inherit;padding:0;color:inherit}.panel-face--text{padding:18px;direction:rtl;text-align:right}.panel .p-label{font-size:17px;line-height:1.7;letter-spacing:0;max-height:135px;overflow:hidden}.panel .p-meta{font-size:11px;letter-spacing:0;margin-top:10px}.panel .p-num{color:#00AF9D}.chapter-list{grid-column:1/-1;display:flex;flex-wrap:wrap;gap:8px;padding-top:20px}.chapter-list button{font-size:14px;text-align:right}\n.lesson-deck{max-width:1200px;margin:30px auto 140px;padding:0 24px;scroll-margin-top:24px}.lesson-slide{position:relative;isolation:isolate;overflow:hidden;min-height:550px;padding:50px 60px;background:var(--lesson-surface);border:1px solid var(--lesson-border);border-radius:24px;box-shadow:0 22px 70px #0003}.lesson-slide[hidden]{display:none}.lesson-slide:before{content:\"\";position:absolute;inset:0;z-index:-1;pointer-events:none;background:linear-gradient(115deg,transparent 25%,#00af9d0b 44%,#ffffff08 50%,transparent 60%);background-size:220% 100%;animation:lesson-light 14s ease-in-out infinite}.slide-label{font-size:14px;color:#00AF9D;margin-bottom:18px}.lesson-slide h2{font-size:clamp(27px,3vw,40px);line-height:1.6;margin-bottom:28px;overflow-wrap:anywhere}.lesson-slide ul{padding-right:24px;font-size:clamp(18px,2vw,24px);line-height:2}.lesson-slide li{margin-bottom:14px;overflow-wrap:anywhere}.lesson-slide figure{margin:28px 0}.lesson-slide img{display:block;max-width:100%;max-height:600px;object-fit:contain;margin:auto;background:#fff;border-radius:12px}.lesson-slide figcaption{font-size:13px;text-align:center;opacity:.7;margin:8px 0}.speaker-notes{border-top:1px solid var(--lesson-border);margin-top:28px;padding-top:18px}.speaker-notes summary{cursor:pointer;color:#00AF9D}.speaker-notes p{font-size:18px;white-space:pre-wrap;margin:18px 0;line-height:2}.lesson-slide footer{font-size:12px;opacity:.65;margin-top:28px}.cover-slide{background:linear-gradient(135deg,#0e4943ee,#0d2424ee)}\n.lesson-controls{position:fixed;bottom:0;left:0;right:0;z-index:50;display:flex;align-items:center;justify-content:center;gap:10px;padding:16px 24px;background:var(--lesson-surface);backdrop-filter:blur(16px);border-top:1px solid var(--lesson-border)}.lesson-controls select{max-width:45vw;width:420px;min-width:0}.lesson-controls option{color:#112b29;background:#fff}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}\nbody.lesson-light{background:#f4f9f8;color:#163d38;--lesson-border:#153d3825;--lesson-surface:#ffffffed}.lesson-light .cover-slide{background:linear-gradient(135deg,#d5f1eb,#f7fbfa)}.lesson-light .panel{color:#fff;background:#194a46cc}.lesson-light .speaker-notes summary{color:#087d70}.motion-paused .aura,.motion-paused .lesson-slide:before{animation-play-state:paused}\n@keyframes lesson-light{0%,100%{background-position:100% 0}50%{background-position:0 0}}\n@media(max-width:760px){.lesson-header{padding:16px;flex-wrap:wrap}.actions button{font-size:13px;padding:7px 10px}.orbital-intro{grid-template-columns:1fr;padding:28px 20px}.orbital-scene{min-height:280px;--ring-radius:210px}.intro-copy h1{font-size:30px}.lesson-slide{padding:28px 22px;min-height:400px}.lesson-deck{padding:0 12px;margin-bottom:180px}.lesson-controls{flex-wrap:wrap;padding:12px}.lesson-controls select{max-width:60vw;width:260px}.lesson-slide ul{font-size:18px}.lesson-slide h2{font-size:27px}.chapter-list{padding-top:0}}\n@media(prefers-reduced-motion:reduce){.aura,.lesson-slide:before{animation:none}*{scroll-behavior:auto!important}}\n@media print{@page{size:A4 landscape;margin:12mm}body,body.lesson-light{background:white!important;color:#111!important}.aura,.stars,.lesson-header,.orbital-intro,.lesson-controls{display:none!important}.lesson-deck{margin:0;padding:0;max-width:none}.lesson-slide,.lesson-slide[hidden]{display:block!important;overflow:visible;min-height:0;border:0;border-radius:0;box-shadow:none;padding:0;background:white!important;break-after:page}.lesson-slide:last-child{break-after:auto}.lesson-slide:before{display:none}.lesson-slide h2{font-size:26px}.lesson-slide ul,.speaker-notes p{font-size:17px}.lesson-slide figure{break-inside:avoid}.lesson-slide img{max-height:125mm}.speaker-notes{content-visibility:visible}.speaker-notes summary{display:none}.slide-label{color:#087d70!important}}\n\n@font-face{font-family:'Pinar VF';src:url(data:font/ttf;base64,) format('truetype');font-style:normal;font-weight:100 900;font-display:swap}body,button,select,input,textarea,.panel,.panel .p-num,.panel .p-label,.panel .p-meta{font-family:'Pinar VF',Tahoma,Arial,sans-serif}\n";
const MOFID_ORBITAL_SCRIPT="/*\n\n    Tooplate 2167 Orbital\n\n    https://www.tooplate.com/view/2167-orbital\n\n    Free HTML CSS Template\n\n*/\n\n(function () {\n  var reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;\n\n  /* Position the orbital ring panels (markup lives in index.html) */\n  var ring = document.getElementById('ring');\n  var panels = ring.querySelectorAll('.panel');\n  var count = panels.length;\n\n  var spacingLevels = [0.74, 0.92, 1.08];   /* tight, default, wide */\n  var spacingIndex = 1;\n\n  function baseRadius() {\n    var raw = getComputedStyle(document.documentElement).getPropertyValue('--ring-radius');\n    return parseFloat(raw) || 360;\n  }\n  function effectiveRadius() {\n    return baseRadius() * spacingLevels[spacingIndex];\n  }\n\n  function positionPanels() {\n    var r = effectiveRadius();\n    panels.forEach(function (panel, i) {\n      var angle = (360 / count) * i;\n      var tilt = Math.sin((i / count) * Math.PI * 2) * 8;\n      panel.style.setProperty('--ry', angle + 'deg');\n      panel.style.setProperty('--tz', r + 'px');\n      panel.style.setProperty('--rz', tilt.toFixed(2) + 'deg');\n      panel.style.setProperty('--i', i);\n    });\n  }\n  positionPanels();\n\n  var resizeTimer;\n  window.addEventListener('resize', function () {\n    clearTimeout(resizeTimer);\n    resizeTimer = setTimeout(positionPanels, 200);\n  });\n\n  /* 3 step spacing updates panel translateZ, the existing transform transition animates it */\n  var spacingSteps = document.querySelectorAll('.spacing-step');\n  function setSpacing(idx) {\n    spacingIndex = idx;\n    var r = effectiveRadius();\n    ring.querySelectorAll('.panel').forEach(function (p) {\n      p.style.setProperty('--tz', r + 'px');\n    });\n    spacingSteps.forEach(function (b) {\n      b.classList.toggle('is-active', parseInt(b.getAttribute('data-space'), 10) === idx);\n    });\n  }\n  spacingSteps.forEach(function (b) {\n    b.addEventListener('click', function () {\n      setSpacing(parseInt(b.getAttribute('data-space'), 10));\n    });\n  });\n\n  /* Ring rotation driven by drag and horizontal scroll, with momentum */\n  var stage = document.querySelector('.stage');\n  var parallax = document.querySelector('.parallax');\n\n  var rotation = 0;\n  var velocity = 0;\n  var baseDrift = reduceMotion ? 0 : 0.12;   /* gentle auto rotation per frame */\n  var friction = 0.94;                        /* momentum decay after a flick */\n  var MAX_VELOCITY = 7;\n  var DRAG_SENS = 0.32;                        /* degrees of spin per pixel dragged */\n  var WHEEL_SENS = 0.05;                       /* spin from horizontal scroll or trackpad */\n\n  var dragging = false;\n  var lastX = 0;\n\n  function clamp(v, min, max) { return Math.max(min, Math.min(max, v)); }\n\n  /* Parallax tilt target */\n  var targetX = 0, targetY = 0, currentX = 0, currentY = 0;\n  var rangeY = 28;   /* horizontal pan */\n  var rangeX = 30;   /* vertical tilt swing */\n  var biasX = 10;    /* lean the ring upward at rest, flip to negative to lean down */\n  if (!reduceMotion) {\n    window.addEventListener('mousemove', function (e) {\n      var mx = (e.clientX / window.innerWidth) - 0.5;\n      var my = (e.clientY / window.innerHeight) - 0.5;\n      targetY = mx * rangeY;\n      targetX = (-my * rangeX) + biasX;\n    });\n  }\n\n  /* Pointer drag spins the ring and carries momentum on release */\n  if (stage) {\n    stage.addEventListener('pointerdown', function (e) {\n      dragging = true;\n      lastX = e.clientX;\n      velocity = 0;\n      stage.classList.add('dragging');\n    });\n    window.addEventListener('pointermove', function (e) {\n      if (!dragging) return;\n      var dx = e.clientX - lastX;\n      lastX = e.clientX;\n      var step = dx * DRAG_SENS;\n      rotation += step;\n      velocity = clamp(step, -MAX_VELOCITY, MAX_VELOCITY);\n    });\n    function endDrag() {\n      if (!dragging) return;\n      dragging = false;\n      stage.classList.remove('dragging');\n    }\n    window.addEventListener('pointerup', endDrag);\n    window.addEventListener('pointercancel', endDrag);\n\n    /* Horizontal scroll or trackpad swipe spins, vertical scroll passes through to the page */\n    stage.addEventListener('wheel', function (e) {\n      if (Math.abs(e.deltaX) > Math.abs(e.deltaY)) {\n        e.preventDefault();\n        velocity = clamp(velocity + e.deltaX * WHEEL_SENS, -MAX_VELOCITY, MAX_VELOCITY);\n      }\n    }, { passive: false });\n  }\n\n  /* Single animation loop for rotation and parallax */\n  function frame() {\n    if (!dragging && !window.mofidOrbitalPaused) {\n      rotation += baseDrift + velocity;\n      velocity *= friction;\n      if (Math.abs(velocity) < 0.0015) velocity = 0;\n    }\n    ring.style.transform = 'rotateY(' + rotation.toFixed(3) + 'deg)';\n\n    if (!reduceMotion && parallax && !window.mofidOrbitalPaused) {\n      currentX += (targetX - currentX) * 0.06;\n      currentY += (targetY - currentY) * 0.06;\n      parallax.style.transform = 'rotateX(' + currentX.toFixed(2) + 'deg) rotateY(' + currentY.toFixed(2) + 'deg)';\n    }\n    requestAnimationFrame(frame);\n  }\n  frame();\n\n  /* Scroll reveal with 3 second fallback for iframe contexts */\n  var revealEls = document.querySelectorAll('.reveal');\n  if ('IntersectionObserver' in window) {\n    var io = new IntersectionObserver(function (entries) {\n      entries.forEach(function (entry) {\n        if (entry.isIntersecting) {\n          entry.target.classList.add('visible');\n          io.unobserve(entry.target);\n        }\n      });\n    }, { threshold: 0.15 });\n    revealEls.forEach(function (el) { io.observe(el); });\n  } else {\n    revealEls.forEach(function (el) { el.classList.add('visible'); });\n  }\n  setTimeout(function () {\n    revealEls.forEach(function (el) { el.classList.add('visible'); });\n  }, 3000);\n\n  /* Mobile menu */\n  var toggle = document.querySelector('.menu-toggle');\n  var mobileMenu = document.querySelector('.mobile-menu');\n  if (toggle && mobileMenu) {\n    toggle.addEventListener('click', function () {\n      var open = mobileMenu.classList.toggle('open');\n      toggle.setAttribute('aria-expanded', open ? 'true' : 'false');\n    });\n    mobileMenu.querySelectorAll('a').forEach(function (link) {\n      link.addEventListener('click', function () {\n        mobileMenu.classList.remove('open');\n        toggle.setAttribute('aria-expanded', 'false');\n      });\n    });\n  }\n  /* Visuals toggle: crossfade panels between text and images */\n  var switchBtn = document.getElementById('visualsSwitch');\n  if (switchBtn) {\n    switchBtn.addEventListener('click', function () {\n      var on = switchBtn.getAttribute('aria-checked') !== 'true';\n      switchBtn.setAttribute('aria-checked', on ? 'true' : 'false');\n      document.body.classList.toggle('visuals-on', on);\n    });\n  }\n\n  /* Zoom toggle: scale the whole ring 20 percent larger */\n  var zoomSwitch = document.getElementById('zoomSwitch');\n  var ringTilt = document.querySelector('.ring-tilt');\n  if (zoomSwitch && ringTilt) {\n    zoomSwitch.addEventListener('click', function () {\n      var on = zoomSwitch.getAttribute('aria-checked') !== 'true';\n      zoomSwitch.setAttribute('aria-checked', on ? 'true' : 'false');\n      ringTilt.style.setProperty('--zoom', on ? '1.24' : '1');\n    });\n  }\n})();\n";
/* Educational adaptation of Tooplate 2167 Orbital. Original asset credits retained. */
function mofidOrbitalHTML(course) {
  const esc = value => String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
  const safeImage = value => /^data:image\/(png|jpe?g|webp|gif);base64,[A-Za-z0-9+/=\s]+$/i.test(String(value || '')) ? value : '';
  const sources = new Map((course.sources || []).map(source => [source.id, source]));
  const slides = course.slides || [];
  if (!slides.length) throw Error('این دوره هنوز اسلاید ندارد.');
  const usedImages = new Set();
  const imageMarkup = refs => (refs || []).flatMap(id => {
    const source = sources.get(id);
    return (source?.images || []).map(image => ({...image, label: source.label}));
  }).filter(image => safeImage(image.data)).filter(image => { if(usedImages.has(image.data)) return false; usedImages.add(image.data); return true; })
    .map(image => '<figure><img src="' + esc(image.data) + '" alt="' + esc(image.caption || image.label) + '" loading="lazy"><figcaption>' + esc(image.caption || image.label) + '</figcaption></figure>').join('');
  const chapters = (course.modules || []).map((module, index) => {
    const refs = new Set((module.sections || []).flatMap(section => section.sourceIds || []));
    let slideIndex = slides.findIndex((slide, i) => i > 0 && (slide.sourceIds || []).some(id => refs.has(id)) && String(slide.title).startsWith(module.title));
    if (slideIndex < 0) slideIndex = slides.findIndex((slide, i) => i > 0 && (slide.sourceIds || []).some(id => refs.has(id)));
    const image = (course.sources || []).filter(source => refs.has(source.id)).flatMap(source => source.images || []).find(image => safeImage(image.data));
    return {title: module.title, index: Math.max(0, slideIndex), image, number: index + 1};
  });
  const panels = (chapters.length ? chapters : [{title: course.title, index: 0, number: 1}]).slice(0,10).map(chapter => '<button class="panel" data-slide="'+chapter.index+'" aria-label="'+esc(chapter.title)+'"><div class="panel-face panel-face--text"><div class="p-num">'+chapter.number+'</div><div><div class="p-label">'+esc(chapter.title)+'</div><div class="p-meta">انتخاب فصل</div></div></div></button>').join('');
  const pages = slides.map((slide,index) => {
    const refs = (slide.sourceIds || []).map(id => sources.get(id)?.label).filter(Boolean);
    const notes = String(slide.notes || '').split(/\n+/).filter(text => text.trim()).map(text => '<p>'+esc(text)+'</p>').join('');
    return '<article class="lesson-slide'+(index===0?' cover-slide':'')+'" id="slide-'+index+'" aria-labelledby="heading-'+index+'"'+(index===0?'':' hidden')+'><div class="slide-label">مفید آکادمی</div><h2 id="heading-'+index+'">'+esc(slide.title)+'</h2><ul>'+ (slide.bullets || []).map(text=>'<li>'+esc(text)+'</li>').join('')+'</ul>'+imageMarkup(slide.sourceIds)+'<details class="speaker-notes"><summary>توضیحات تکمیلی و یادداشت مدرس</summary>'+notes+'</details>'+(refs.length?'<footer>منبع: '+esc([...new Set(refs)].join('، '))+'</footer>':'')+'</article>';
  }).join('');
  const list = slides.map((slide,index)=>'<option value="'+index+'">'+(index+1)+' — '+esc(slide.title)+'</option>').join('');
  const script = '(' + mofidOrbitalPlayer.toString() + ')();';
  return '<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+esc(course.title)+' — مفید آکادمی</title><style>'+MOFID_ORBITAL_CSS+'\n'+MOFID_LESSON_CSS+'</style></head><body><div class="aura"></div><div class="stars"></div><header class="lesson-header"><strong>مفید آکادمی</strong><div class="actions"><button id="theme">حالت روشن</button><button id="motion" aria-pressed="false">توقف حرکت</button><button id="fullscreen">تمام‌صفحه</button><button id="print">چاپ / PDF</button></div></header><main><section class="orbital-intro" id="intro"><div class="intro-copy"><span>ارائهٔ آموزشی</span><h1>'+esc(course.title)+'</h1><p>'+esc(course.description || '')+'</p><button class="start" data-slide="0">شروع ارائه</button></div><div class="orbital-scene"><div class="stage"><div class="parallax"><div class="ring-tilt"><div class="ring" id="ring">'+panels+'</div></div></div></div></div><nav class="chapter-list" aria-label="فهرست همهٔ فصل‌ها">'+chapters.map(chapter=>'<button data-slide="'+chapter.index+'">'+esc(chapter.number+' · '+chapter.title)+'</button>').join('')+'</nav></section><section class="lesson-deck" id="deck" aria-label="اسلایدها">'+pages+'</section></main><nav class="lesson-controls" aria-label="کنترل ارائه"><button id="prev">قبلی</button><label for="slide-picker" class="sr-only">انتخاب اسلاید</label><select id="slide-picker">'+list+'</select><span id="counter" aria-live="polite"></span><button id="next">بعدی</button><button id="contents">فهرست فصل‌ها</button></nav><script>'+MOFID_ORBITAL_SCRIPT.replace(/<\/script/gi,'<\\/script')+'<\/script><script>'+script+'<\/script></body></html>';
}
function mofidOrbitalPlayer() {
  const slides = [...document.querySelectorAll('.lesson-slide')];
  const picker = document.getElementById('slide-picker');
  let index = 0;
  function show(next, scroll = true) {
    index = Math.max(0, Math.min(slides.length - 1, Number(next) || 0));
    slides.forEach((slide,i) => { slide.hidden = i !== index; });
    picker.value = String(index);
    document.getElementById('counter').textContent = (index+1)+' / '+slides.length;
    document.getElementById('prev').disabled = index === 0;
    document.getElementById('next').disabled = index === slides.length - 1;
    if(scroll) document.getElementById('deck').scrollIntoView({behavior:'auto', block:'start'});
  }
  document.querySelectorAll('[data-slide]').forEach(button=>button.addEventListener('click',()=>show(button.dataset.slide)));
  document.getElementById('prev').onclick = ()=>show(index-1);
  document.getElementById('next').onclick = ()=>show(index+1);
  picker.onchange = ()=>show(picker.value);
  document.getElementById('contents').onclick = ()=>document.getElementById('intro').scrollIntoView({behavior:'auto'});
  document.getElementById('theme').onclick = event=>{document.body.classList.toggle('lesson-light');event.target.textContent=document.body.classList.contains('lesson-light')?'حالت تاریک':'حالت روشن';};
  document.getElementById('motion').onclick = event=>{window.mofidOrbitalPaused=!window.mofidOrbitalPaused;document.body.classList.toggle('motion-paused',window.mofidOrbitalPaused);event.target.setAttribute('aria-pressed',String(window.mofidOrbitalPaused));event.target.textContent=window.mofidOrbitalPaused?'ادامه حرکت':'توقف حرکت';};
  document.getElementById('fullscreen').onclick = async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{document.getElementById('fullscreen').textContent='تمام‌صفحه در این مرورگر پشتیبانی نمی‌شود';}};
  document.getElementById('print').onclick = ()=>window.print();
  document.addEventListener('keydown',event=>{if(/INPUT|TEXTAREA|SELECT|BUTTON/.test(event.target.tagName)||event.ctrlKey||event.metaKey||event.altKey)return;if(['ArrowLeft','PageDown',' '].includes(event.key)){event.preventDefault();show(index+1);}if(['ArrowRight','PageUp'].includes(event.key)){event.preventDefault();show(index-1);}});
  let openNotes=[];
  window.addEventListener('beforeprint',()=>{openNotes=[...document.querySelectorAll('.speaker-notes')].filter(note=>note.open);document.querySelectorAll('.speaker-notes').forEach(note=>note.open=true);});
  window.addEventListener('afterprint',()=>{document.querySelectorAll('.speaker-notes').forEach(note=>note.open=openNotes.includes(note));show(index,false);});
  show(0,false);
}
async function mofidOrbitalDownload(course) {
  try {
    const html = mofidOrbitalHTML(course);
    const url = URL.createObjectURL(new Blob([html], {type:'text/html;charset=utf-8'}));
    const anchor = document.createElement('a'); anchor.href=url;anchor.download=String(course.title || 'mofid-presentation').replace(/[\\/:*?"<>|]/g,'-')+'-presentation.html';
    document.body.appendChild(anchor);anchor.click();anchor.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);
  } catch(error) { ym.error(error.message || 'خروجی ارائه آماده نشد.'); }
}
